import string

HEX_DIGITS = set(string.hexdigits)


def _unquote(s: str) -> str:
    s = s.replace("+", " ")
    parts = s.split("%")
    if len(parts) == 1:
        return parts[0]

    res = bytearray(parts[0].encode("latin1"))
    for part in parts[1:]:
        if len(part) < 2 or part[0] not in HEX_DIGITS or part[1] not in HEX_DIGITS:
            raise ValueError(f"Malformed percent-escape in: {s}")
        res.append(int(part[:2], 16))
        res.extend(part[2:].encode("latin1"))

    return res.decode("utf-8")


def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result

    pairs = qs.split("&")
    for pair in pairs:
        if not pair:
            continue
        if "=" in pair:
            key, val = pair.split("=", 1)
        else:
            key, val = pair, ""

        decoded_key = _unquote(key)
        decoded_val = _unquote(val)

        result.setdefault(decoded_key, []).append(decoded_val)

    return result
